"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[554],{5538(e){e.exports=JSON.parse('{"tag":{"label":"Brute Force","permalink":"/concepts/tags/brute-force","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"brute-force/brute-force-and-exhaustive-search","title":"Brute Force and Exhaustive Search","description":"Brute force is the most direct way to design an algorithm: solve the problem by doing exactly what its statement says, with no attempt to exploit its structure. To find an element, look at every position. To find the best combination, generate every combination and keep the best one. To check whether a text contains a word, try the word at every position of the text.","permalink":"/concepts/brute-force/brute-force-and-exhaustive-search"},{"id":"brute-force/exercises","title":"Exercises: Brute Force","description":"These exercises review the lesson on brute force and exhaustive search. Most of them ask the same two questions the solutions are grouped at the end of the page.","permalink":"/concepts/brute-force/exercises"},{"id":"brute-force/summary","title":"Summary: Brute Force","description":"Everything on one page, to review the chapter before moving on.","permalink":"/concepts/brute-force/summary"}],"unlisted":false}}')}}]);